package localchat;
import java.awt.*;import java.nio.file.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.AtomicInteger;import javax.swing.*;
/** Regression for the reported prose-only confirmation and independent action checkboxes. */
public final class InteractionCardsTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static List<Component> all(Component c){return ComposerAssistTest.all(c);}
 static List<JCheckBox> boxes(ComposerAssist a){return all(a).stream().filter(c->c instanceof JCheckBox).map(c->(JCheckBox)c).toList();}
 static List<JTextField> fields(ComposerAssist a){return all(a).stream().filter(c->c instanceof JTextField).map(c->(JTextField)c).toList();}
 static Map<String,Object> multi(){return Json.obj("message","Alege operatiile confirmate","questions",List.of(Json.obj("id","actions","question","Ce grupuri copiez?","multiple",true,"options",List.of("TR + DWG","GP numai V","PP01"))),"suggestions",List.of());}
 static final String PROSE="Ce trebuie facut imediat — si am nevoie de un raspuns de la tine\nLista de import este in Complete lijst. Trebuie mutata in Import?\n\nPasi pregatiti, astept confirmare\nDupa raspunsul tau, execut in ordine:\n1. Mut lista in Import\n2. Copiez PDF V/W\n3. Copiez Merkenoverzicht\n4. Verific brosura\n5. Oprit GP, nu copiez GP\n\nIntrebarea pentru tine: BP merge la fabrica A sau ramane la fabrica B?\nMai am si o intrebare tehnica: catalogul este acelasi sau altul?";
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");
  var detected=ComposerAssist.detect(PROSE);check(detected!=null&&detected.questions().size()==4,"reported prose exposes action selection and all three missing answers");check(detected.questions().stream().filter(q->!q.multiple()).allMatch(q->!q.options().isEmpty()),"plain yes/no and literal alternatives become selectable choices");check(ComposerAssist.detect("Pasul urmator: Verifica raportul final.").suggestions().size()==1,"explicit prose next step becomes optional card without extra inference");check(detected.questions().stream().filter(ComposerAssist.Question::multiple).count()==1,"independent action list uses checkboxes");
  check(ComposerAssist.detect("Astept confirmarea.\n```\nIntrebarea pentru tine: trebuie copiat?\n```\n> Trebuie mutat?")==null,"quoted/fenced document examples do not create cards");check(ComposerAssist.detect("Astept confirmarea.\n1. Fabrica A\n2. Fabrica B")==null,"arbitrary exclusive location alternatives are never guessed as independent actions");check(ComposerAssist.detect("Am finalizat.\n1. Copiat PDF\n2. Copiat DWG")==null,"completed lists do not become approval requests");
  for(String[] sample:new String[][]{{"Waiting for your answer. Should I copy it?"},{"Ik wacht op bevestiging. Welke fabriek kies je?"},{"Espero confirmacion. ¿Quieres copiarlo?"},{"Czekam na potwierdzenie. Czy kopiowac?"},{"Onay bekliyorum. Hangi fabrika?"}})check(ComposerAssist.detect(sample[0])!=null,"localized explicit unanswered question");
  FeatureTest.edt(()->{
   var input=new ComposerAssist.GhostInput();input.setText("Ciorna mea separata");AtomicInteger submitted=new AtomicInteger();String[] result={""};var a=new ComposerAssist(input,s->{submitted.incrementAndGet();result[0]=s;});a.present(multi(),"multi");check(boxes(a).size()==3&&!a.send.isEnabled()&&boxes(a).stream().noneMatch(AbstractButton::isSelected),"checkboxes have no default authorization");boxes(a).get(0).doClick();boxes(a).get(2).doClick();fields(a).get(0).setText("Doar dupa verificarea hash");check(boxes(a).get(0).isSelected()&&boxes(a).get(2).isSelected(),"multiple selection and custom qualifier coexist");String saved=a.snapshot();var b=new ComposerAssist(new ComposerAssist.GhostInput(),s->{});b.restore(ComposerAssistTest.history(multi()),saved.replace("multi","request"));check(boxes(b).get(0).isSelected()&&!boxes(b).get(1).isSelected()&&boxes(b).get(2).isSelected()&&fields(b).get(0).getText().contains("hash"),"partial checkbox selection and free text restore without inference");a.busy(true);check(boxes(a).stream().noneMatch(Component::isEnabled)&&!a.send.isEnabled(),"busy prevents checkbox changes and submission");a.busy(false);check(input.getText().equals("Ciorna mea separata")&&submitted.get()==0,"selection never writes into composer or sends");a.send.doClick();check(submitted.get()==1&&result[0].contains("[x] TR + DWG")&&result[0].contains("[ ] GP numai V")&&result[0].contains("[x] PP01")&&result[0].contains("hash"),"explicit submit distinguishes selected and unselected actions and qualifier");
   a.present(ComposerAssistTest.suggestions(),"next");check(!a.waiting()&&!a.send.isEnabled(),"optional next action does not block editor or select by default");var radios=all(a).stream().filter(c->c instanceof JRadioButton).map(c->(JRadioButton)c).toList();radios.get(1).doClick();check(input.getText().equals("Ciorna mea separata")&&submitted.get()==1,"next-action selection is a card, not inserted prompt");a.send.doClick();check(submitted.get()==2&&result[0].equals("Arata verificarile ramase."),"next action can be sent directly from card");a.present(ComposerAssistTest.suggestions(),"custom-next");fields(a).get(0).setText("Explica doar raportul");a.send.doClick();check(result[0].equals("Explica doar raportul"),"free alternative to next action");
   for(String lang:I18n.CODES){I18n.setLanguage(lang);a.present(multi(),"appearance-"+lang);check(all(a).stream().anyMatch(c->c instanceof JTextArea area&&area.getText().contains(I18n.text("Poti bifa mai multe optiuni."))),"multiple-selection label translated "+lang);check(I18n.contains("Ce actiuni alegi?"),"fallback title translated "+lang);}I18n.setLanguage("ro");a.restore(List.of(ChatClient.Message.user("new")),saved);check(!a.isVisible(),"new chat clears prior card");
  });
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer(PROSE,50,20)),FeatureTest.json(FeatureTest.answer("Raspuns primit",30,5)))){
   LocalChat[] app={null};FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("app"),server.url());app[0].setSize(1500,1050);app[0].addNotify();app[0].validate();});NormalModeTest.ask(app[0],"Verifica situatia si intreaba-ma ce lipseste.");
   FeatureTest.edt(()->{ComposerAssist a=FeatureTest.field(app[0],"composerAssist");check(a.waiting()&&a.isVisible()&&server.requests.size()==1,"plain model reply creates visible interactive card without second inference");check(boxes(a).size()==5&&fields(a).size()==4,"all questions and action checkboxes visible from screenshot scenario");AttachmentTest.input(app[0]).setText("Mesaj ramas in asteptare");boxes(a).get(1).doClick();for(JTextField f:fields(a))if(f!=fields(a).get(0))f.setText("Raspuns explicit");for(int theme=0;theme<2;theme++){((JComboBox<?>)FeatureTest.field(app[0],"themeBox")).setSelectedIndex(theme);app[0].validate();java.awt.image.BufferedImage image=new java.awt.image.BufferedImage(1500,1050,java.awt.image.BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();app[0].getRootPane().printAll(g);g.dispose();javax.imageio.ImageIO.write(image,"png",home.resolve(theme==1?"cards-dark.png":"cards-light.png").toFile());}check(AttachmentTest.input(app[0]).getText().equals("Mesaj ramas in asteptare"),"theme switch and choices preserve editable draft");a.send.doClick();});FeatureTest.idle(app[0]);
   FeatureTest.edt(()->{check(server.requests.size()==2,"only explicit card submit starts next request");String question=NormalModeTest.history(app[0]).stream().filter(m->m.role.equals("user")).reduce((a,b)->b).orElseThrow().content;check(question.contains("[x] Copiez PDF V/W")&&question.contains("[ ] Mut lista in Import")&&question.contains("Mesaj ramas in asteptare"),"wire answer includes precise choices plus queued message");check(!FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting(),"answered legacy card does not reappear");app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(Window w:Window.getWindows())w.dispose();});}
  System.out.println("PASS: "+checks+" interactive card checks; screenshots: "+home);System.exit(0);
 }
}
